const $=selector=>document.querySelector(selector);
const state={token:sessionStorage.getItem('chronicle-key')||'',campaign:sessionStorage.getItem('chronicle-campaign')||'',view:'overview',filter:'all',query:'',review:null,data:null,me:null,graph:null};
const names={overview:'Overview',sessions:'Sessions',reviews:'Review queue',wiki:'Compendium',timeline:'Timeline',quests:'Quest log',journals:'Journals',artifacts:'Artifacts',map:'Relationship map',analytics:'Cast analysis',ask:'Ask Chronicle',settings:'Campaign settings',preferences:'My notifications',search:'Search'};
const icons={pc:'♙',npc:'♟',item:'◇',location:'⌂',faction:'⚑',quest:'⚑',journal:'▣',moment:'✦',event:'⌁',award:'✧',quote:'❞',artifact:'✦',arc:'⌁',collection:'▦'};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=value=>new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
const time=seconds=>[Math.floor(seconds/3600),Math.floor(seconds/60)%60,Math.floor(seconds)%60].map(v=>String(v).padStart(2,'0')).join(':');
const admin=()=>['owner','admin'].includes(state.data?.role);
const records=kind=>(state.data?.records||[]).filter(r=>!kind||r.kind===kind);
const button=(label,action,data={},style='')=>`<button type="button" class="button ${style}" data-action="${action}" ${Object.entries(data).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ')}>${label}</button>`;
const badge=(text,type='')=>`<span class="badge ${type}">${esc(String(text).replaceAll('_',' '))}</span>`;
const header=(title,subtitle,actions='')=>`<div class="page-head"><div><p class="eyebrow">${esc(state.data?.campaign.name||'CHRONICLE')}</p><h1>${title}</h1><p class="muted">${subtitle}</p></div><div class="actions">${actions}</div></div>`;
const empty=(title,body,action='')=>`<div class="empty"><div class="empty-mark">✧</div><h3>${title}</h3><p>${body}</p>${action}</div>`;
function rich(text) {
  const renderer=new window.marked.Renderer();renderer.html=token=>esc(token.text||token);
  const html=window.DOMPurify.sanitize(window.marked.parse(String(text||''),{renderer}),{FORBID_TAGS:['img','button','input','form','style']});
  const container=document.createElement('div');container.innerHTML=html;const walker=document.createTreeWalker(container,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  for(const node of nodes){const expression=/\[\[([^\]]+)\]\]/g;let match,last=0,changed=false;const fragment=document.createDocumentFragment();while((match=expression.exec(node.textContent))){const record=records().find(r=>[r.name,...(r.properties.aliases||[])].some(alias=>alias.toLowerCase()===match[1].toLowerCase()));if(!record)continue;fragment.append(node.textContent.slice(last,match.index));const link=document.createElement('button');link.className='wiki-link';link.dataset.action='open-record';link.dataset.id=record.id;link.textContent=match[1];fragment.append(link);last=expression.lastIndex;changed=true;}if(changed){fragment.append(node.textContent.slice(last));node.replaceWith(fragment);}}
  for(const link of container.querySelectorAll('a')){link.target='_blank';link.rel='noopener noreferrer';}
  return container.innerHTML;
}

function notify(text,error=false) {$('#toast').textContent=text;$('#toast').classList.remove('hidden');$('#toast').classList.toggle('error',error);clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.add('hidden'),6500);}
async function api(path,options={}) {
  const headers={Authorization:`Bearer ${state.token}`,...(options.body && !(options.body instanceof File)?{'Content-Type':'application/json'}:{}),...options.headers};
  const response=await fetch(path,{...options,headers,body:options.body && !(options.body instanceof File)?JSON.stringify(options.body):options.body});
  if (!response.ok) {const result=await response.json().catch(()=>({error:'Request failed.'}));throw new Error(result.error);}
  return response.json();
}
const route=path=>`/api/campaigns/${state.campaign}/${path}`;
async function download(path,name) {const response=await fetch(path,{headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok)throw new Error((await response.json()).error);const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function modal(title,html) {$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal();}
function formModal(title,html,onSubmit,label='Save') {
  modal(title,`<form id="modal-form">${html}<div class="actions"><button type="submit" class="button primary">${label}</button><button type="button" class="button" data-action="close">Cancel</button></div></form>`);
  $('#modal-form').onsubmit=async event=>{event.preventDefault();const submit=event.target.querySelector('[type=submit]');submit.disabled=true;try{await onSubmit(new FormData(event.target));$('#modal').close();await refresh();}catch(error){notify(error.message,true);}finally{submit.disabled=false;}};
}
async function boot() {
  if(!state.token){$('#login').classList.remove('hidden');$('#shell').classList.add('hidden');return;}
  try {
    state.me=await api('/api/me');const campaigns=await api('/api/campaigns');
    if(!campaigns.some(c=>c.id===state.campaign))state.campaign=campaigns[0]?.id||'';
    $('#campaign-picker').innerHTML=campaigns.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')||'<option>No campaigns yet</option>';
    $('#campaign-picker').value=state.campaign;$('#actor-avatar').textContent=state.me.subject.slice(0,1).toUpperCase();
    $('#create-campaign').classList.toggle('hidden',!state.me.root);$('#login').classList.add('hidden');$('#shell').classList.remove('hidden');
    await refresh();
  }catch(error){$('#login-error').textContent=error.message;$('#login').classList.remove('hidden');$('#shell').classList.add('hidden');}
}
async function refresh() {
  if(!state.campaign){$('#content').innerHTML=header('Your next chapter starts here.','Create a campaign, or start the Discord bot and use /campaign create.')+empty('An archive waiting for a story','Import your first session to build a world you can return to.',state.me.root?button('＋ Create a campaign','create-campaign',{},'primary'):'');return;}
  state.data=await api(route('state'));sessionStorage.setItem('chronicle-campaign',state.campaign);
  document.querySelectorAll('.admin-only').forEach(el=>el.classList.toggle('hidden',!admin()));
  $('#review-badge').textContent=state.data.reviews.filter(r=>r.state==='pending').length||'';
  $('#host-status').textContent=state.me.share?'Read-only shared archive':state.me.discord?.connected?'Discord connected':state.me.discord?'Discord reconnecting…':'Dashboard only (bot not running)';$('#host-status-box')?.classList.toggle('offline',!state.me.share&&!state.me.discord?.connected);
  if(!admin()&&state.view==='reviews')state.view='overview';await render();
}
async function navigate(view) {state.view=view;state.filter='all';state.query='';$('#search-input').value='';$('.sidebar').classList.remove('open');await render();}
async function render() {
  if(!state.data)return;
  $('#breadcrumb').innerHTML=`Workspace <span>/</span> ${esc(names[state.view]||state.view)}`;
  document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));
  const fn=views[state.view]||views.overview;await fn();decorateEntryCards();decorateReviewKinds();
}
function sessionRow(session) {
  const d=new Date(session.started);return `<div class="session-row"><div class="date-box"><strong>${d.getDate()}</strong><small>${d.toLocaleDateString(undefined,{month:'short'})}</small></div><div class="row-main"><h3>${esc(session.title)}</h3><p>Session ${session.id} · ${date(session.started)}</p></div>${badge(session.state,session.state==='awaiting_review'?'pending':session.state==='approved'?'':'neutral')}${button('Open ↗','open-session',{id:session.id},'small')}</div>`;
}
function questRow(quest) {const objectives=quest.properties.objectives||[],done=objectives.filter(o=>o.status==='done').length;return `<div class="quest-row"><h3><span>⚑</span> ${esc(quest.name)}</h3><p>${esc(quest.properties.nextAction||quest.body).slice(0,140)}</p><progress max="${objectives.length||1}" value="${done}"></progress><small>${done} of ${objectives.length} objectives · ${esc(quest.properties.status||'planned')}</small></div>`;}
function cards(rows) {return rows.length?`<div class="card-grid">${rows.map(row=>`<article class="entry-card" tabindex="0" role="button" data-action="open-record" data-id="${row.id}"><div class="actions"><span class="entry-icon">${icons[row.kind]||'◇'}</span>${badge(row.kind)}${row.visibility!=='party'?badge(row.visibility,'private'):''}</div><h3>${esc(row.name)}</h3><p class="description">${esc(ovPlain(row.body).slice(0,270))}</p><div class="tags">${row.tags.slice(0,5).map(tag=>`<span class="tag">${esc(tag)}</span>`).join('')}</div></article>`).join('')}</div>`:empty('Nothing here yet','Entries will appear as you approve session reviews. You can also create them by hand.');}
function match(row){return !state.query||(row.name+' '+row.body+' '+row.tags.join(' ')).toLowerCase().includes(state.query.toLowerCase());}
function decorateEntryCards(){for(const card of document.querySelectorAll('.entry-card')){const row=records().find(item=>item.id===card.dataset.id);if(row?.properties?.asset&&!card.querySelector('.entry-card-image')){const image=document.createElement('img');image.className='entry-card-image';image.alt='';image.dataset.authSrc=route(`records/${row.id}/image`);card.prepend(image);fetch(image.dataset.authSrc,{headers:{Authorization:`Bearer ${state.token}`}}).then(r=>r.ok?r.blob():null).then(blob=>{if(blob)image.src=URL.createObjectURL(blob);}).catch(()=>{});}}}
function decorateReviewKinds(){
  const form=$('#review-form'),reviewId=state.review;if(!form||!reviewId)return;
  const review=state.data.reviews.find(row=>row.id===reviewId);if(!review)return;
  form.querySelectorAll('.review-fact').forEach((detail,index)=>{
    const fact=review.payload.facts[index],fields=detail.querySelector('.fact-fields'),target=fields?.querySelector(`[name="target-${index}"]`);if(!fact||!fields||!target)return;
    const label=document.createElement('label');label.textContent='Entry type';const select=document.createElement('select');select.name=`kind-${index}`;select.innerHTML=['pc','npc','item','location','faction','quest','event','moment','award','quote'].map(kind=>`<option value="${kind}" ${kind===fact.kind?'selected':''}>${kind}</option>`).join('');label.append(select);fields.insertBefore(label,fields.firstChild);
    select.onchange=()=>{const current=target.value;target.innerHTML='<option value="">Create a new entry / match its exact name</option>'+records(select.value).map(row=>`<option value="${row.id}">${esc(row.name)}</option>`).join('');if(records(select.value).some(row=>row.id===current))target.value=current;};
  });
  form.addEventListener('submit',()=>form.querySelectorAll('[name^="kind-"]').forEach((select,index)=>{review.payload.facts[index].kind=select.value;}),{capture:true});
}

// Overview helpers (tavern design concept).
const OV_PATHS={arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',play:'<path d="M8 5l11 7-11 7z" fill="currentColor"/>',stop:'<rect x="7" y="7" width="10" height="10" rx="1.5" fill="currentColor"/>',book:'<path d="M3 5.5C5.5 4.5 8.5 4.5 12 6.5v13c-3.5-2-6.5-2-9-1z"/><path d="M21 5.5c-2.5-1-5.5-1-9 1v13c3.5-2 6.5-2 9-1z"/>',bag:'<path d="M5 8h14l-1 12H6z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/>',bookmark:'<path d="M7 3h10v18l-5-4-5 4z"/>',scroll:'<path d="M7 4h11a2 2 0 0 1 2 2v1h-4"/><path d="M16 7v11a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2v-1h10"/><path d="M7 4a2 2 0 0 0-2 2v11"/><path d="M8.5 9h5M8.5 12.5h5"/>',person:'<circle cx="12" cy="8" r="3.6"/><path d="M5 20c0-3.9 3.1-7 7-7s7 3.1 7 7"/>',lock:'<rect x="5" y="10.5" width="14" height="10" rx="2"/><path d="M8 10.5V8a4 4 0 0 1 8 0v2.5"/>',spark:'<path d="M12 3l1.8 6.2L20 11l-6.2 1.8L12 19l-1.8-6.2L4 11l6.2-1.8z"/>',send:'<path d="M4 4.5l16 7.5-16 7.5 3-7.5z" fill="currentColor" stroke="none"/>',link:'<path d="M10 14a4 4 0 0 0 5.7 0l3-3a4 4 0 0 0-5.7-5.7l-1 1"/><path d="M14 10a4 4 0 0 0-5.7 0l-3 3a4 4 0 0 0 5.7 5.7l1-1"/>',key:'<circle cx="8" cy="12" r="3.5"/><path d="M11.5 12H21M18 12v3M15 12v2"/>',flask:'<path d="M10 3h4M10.5 3v5.5L5.5 18a2 2 0 0 0 1.8 3h9.4a2 2 0 0 0 1.8-3l-5-9.5V3"/><path d="M7.5 15h9"/>',coins:'<ellipse cx="9" cy="7" rx="5" ry="2.5"/><path d="M4 7v4c0 1.4 2.2 2.5 5 2.5s5-1.1 5-2.5V7"/><ellipse cx="15" cy="14" rx="5" ry="2.5"/><path d="M10 14v3.5c0 1.4 2.2 2.5 5 2.5s5-1.1 5-2.5V14"/>',sword:'<path d="M14.5 4H20v5.5L9 20.5 3.5 15z"/><path d="M6 12.5l5.5 5.5M4 20l2.5-2.5"/>',pin:'<path d="M12 21s-6-6.1-6-11a6 6 0 0 1 12 0c0 4.9-6 11-6 11z"/><circle cx="12" cy="10" r="2.2"/>'};
const ovIcon=name=>`<svg class="svg-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${OV_PATHS[name]||OV_PATHS.spark}</svg>`;
const ovPlain=text=>String(text||'').replace(/\[\[([^\]|]+)(?:\|([^\]]+))?\]\]/g,(_,a,b)=>b||a).replace(/[*#`>_]/g,'').replace(/\s+/g,' ').trim();
function ovBullets(text,max=3){const lines=String(text||'').split(/\r?\n/).map(l=>l.match(/^\s*[-*•]\s+(.*)$/)?.[1]).filter(Boolean).map(ovPlain);if(lines.length)return lines.slice(0,max);return (ovPlain(text).match(/[^.!?]+[.!?]+/g)||[ovPlain(text)]).slice(0,max).map(s=>s.trim()).filter(Boolean);}
const ovName=value=>typeof value==='string'?(records().find(r=>r.id===value)?.name||value):value&&typeof value==='object'?(value.text||value.name||''):String(value??'');
const ovCarried=item=>{const p=item.properties||{};return !['dropped','stored','given','sold','used','lost'].includes(p.status)&&(p.holder||!p.location);};
function ovItemLine(item){const p=item.properties||{},parts=[];const shared=p.holder&&/party|shared/i.test(ovName(p.holder));if(Number(p.quantity)>1)parts.push(`${Number(p.quantity)} ${shared?'shared':'carried'}`);if(p.holder&&!shared)parts.push(`Held by ${ovName(p.holder)}`);else if(!p.holder&&p.location)parts.push(`At ${ovName(p.location)}`);if(!parts.length&&p.status)parts.push(String(p.status).replace('_',' '));return parts.join(' · ')||'Item';}
const ovItemIcon=item=>[[/key/i,'key'],[/potion|elixir|vial|flask|tonic/i,'flask'],[/coin|silver|gold|copper|gem|jewel/i,'coins'],[/sword|blade|dagger|axe|bow|spear|mace|hammer/i,'sword'],[/letter|scroll|map|note|book|page/i,'scroll']].find(([p])=>p.test(item.name))?.[1]||'bag';
function ovFeatured(last,lastSeen){const npcs=records('npc');if(!npcs.length)return records('pc')[0]||null;const quotes=records('quote');const score=p=>((last&&(p.sources||[]).some(s=>s.session===last.id))?10:0)+(quotes.some(q=>q.properties.speaker===p.id)?5:0)+(Array.isArray(p.properties.history)?p.properties.history.length:0)+lastSeen(p)/100;return [...npcs].sort((a,b)=>score(b)-score(a))[0];}
function ovMyNote(){return state.me&&!state.me.share?records('journal').find(r=>r.name==='My note'&&r.author===state.me.subject)||null:null;}
function ovProfile(person,label,num){
  const p=person.properties||{},likes=(Array.isArray(p.likes)?p.likes:p.likes?[p.likes]:[]).map(ovName);
  const history=(Array.isArray(p.history)?p.history:[]).filter(h=>typeof h==='object'?h.text:h),lastH=history.at(-1);
  const quote=records('quote').filter(q=>q.properties.speaker===person.id).sort((a,b)=>Math.max(0,...(b.sources||[]).map(s=>num(s.session)))-Math.max(0,...(a.sources||[]).map(s=>num(s.session))))[0];
  const ids=new Set();for(const v of Object.values(p))for(const x of Array.isArray(v)?v:[v])if(typeof x==='string'&&records().some(r=>r.id===x))ids.add(x);
  for(const m of String(person.body||'').matchAll(/\[\[([^\]|]+)/g)){const t=records().find(r=>r.name.toLowerCase()===m[1].trim().toLowerCase());if(t)ids.add(t.id);}
  for(const r of records())if(r.id!==person.id&&!['quote','moment','award','journal'].includes(r.kind)&&Object.values(r.properties||{}).flat().includes(person.id))ids.add(r.id);
  ids.delete(person.id);const linked=[...ids].map(id=>records().find(r=>r.id===id)).filter(r=>r&&!['quote','moment','award'].includes(r.kind)).slice(0,4);
  const meta=[p.role||p.class||(person.kind==='pc'?'Player character':'NPC'),p.home?ovName(p.home):p.species].filter(Boolean);
  const src=quote?.sources?.[0];
  return `<section class="ov-card"><p class="eyebrow ov-eyebrow">${ovIcon('person')} People / saved profile</p>
    <div class="ov-profile-top"><span class="ov-portrait">${p.asset?`<img alt="" data-auth-src="${route('records/'+person.id+'/image')}">`:esc(person.name.split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase())}</span><div><h3>${esc(person.name)}</h3><p class="muted ov-meta">${meta.map(esc).join(' · ')}</p><p class="ov-blurb">${esc(ovPlain(person.body).slice(0,150))}${ovPlain(person.body).length>150?'…':''}</p></div></div>
    <div>${likes.length?`<div class="ov-fact"><span class="eyebrow ov-eyebrow">Known likes</span><span class="ov-chips">${likes.map(l=>`<span class="ov-chip">${esc(l)}</span>`).join('')}</span></div>`:''}
    ${lastH?`<div class="ov-fact"><span class="eyebrow ov-eyebrow">Last interaction</span><span>${esc(typeof lastH==='object'?lastH.text:lastH)}${typeof lastH==='object'&&lastH.session&&num(lastH.session)?` <span class="muted">· ${label(lastH.session)}</span>`:''}</span></div>`:''}
    ${quote?`<div class="ov-fact stack"><span class="eyebrow ov-eyebrow">Words to remember</span><p class="ov-quote">“${esc(ovPlain(quote.body))}”</p>${src&&num(src.session)?`<span class="muted ov-small">${label(src.session)}</span>`:''}</div>`:''}
    ${linked.length?`<div class="ov-fact"><span class="muted ov-inline">${ovIcon('link')} Connected to</span><span class="ov-chips">${linked.map(r=>`<button type="button" class="ov-chip" data-action="open-record" data-id="${r.id}">${esc(r.name)}</button>`).join('')}</span></div>`:''}</div>
    <div class="ov-center"><button type="button" class="button gold" data-action="open-record" data-id="${person.id}">Open profile ${ovIcon('arrow')}</button></div></section>`;
}
function ovScene(backdrop=null){
  if(backdrop?.properties?.asset)return `<img class="ov-scene ov-scene-image" data-auth-src="${route(`records/${backdrop.id}/image`)}" alt="${esc(backdrop.name||'Session backdrop')}">`;
  const rain=Array.from({length:38},(_,i)=>{const x=(i*53)%420,y=(i*37)%220;return `<line x1="${x}" y1="${y}" x2="${x-6}" y2="${y+18}"/>`;}).join('');
  return `<svg class="ov-scene" viewBox="0 0 420 260" preserveAspectRatio="xMaxYMax slice" aria-hidden="true"><defs><radialGradient id="ovglow" cx="50%" cy="50%" r="50%"><stop offset="0" stop-color="#ffcf7a" stop-opacity=".9"/><stop offset="1" stop-color="#ffcf7a" stop-opacity="0"/></radialGradient><linearGradient id="ovwall" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#2a2420"/><stop offset="1" stop-color="#15110d"/></linearGradient></defs><g stroke="#9fb3c8" stroke-opacity=".18" stroke-width="1">${rain}</g><path d="M150 260V130l70-58 70 58v130z" fill="url(#ovwall)"/><path d="M140 134l80-70 80 70" fill="none" stroke="#3b3128" stroke-width="10"/><path d="M270 260V150l55-40 60 40v110z" fill="#1b1612"/><path d="M262 154l63-48 68 48" fill="none" stroke="#352b23" stroke-width="8"/><rect x="250" y="40" width="14" height="60" fill="#211b16"/><g fill="#f2b45a"><rect x="175" y="150" width="20" height="26" rx="2"/><rect x="245" y="150" width="20" height="26" rx="2"/><rect x="300" y="170" width="16" height="22" rx="2"/><rect x="345" y="170" width="16" height="22" rx="2"/><rect x="208" y="100" width="24" height="22" rx="2"/></g><g fill="url(#ovglow)" opacity=".7"><circle cx="185" cy="163" r="26"/><circle cx="255" cy="163" r="26"/><circle cx="220" cy="111" r="22"/><circle cx="308" cy="181" r="18"/><circle cx="353" cy="181" r="18"/></g><rect x="203" y="205" width="34" height="55" rx="3" fill="#120e0b" stroke="#3b3128"/><path d="M0 252c90-14 220-12 420 2v6H0z" fill="#0f0c0a"/></svg>`;
}
let ovSpeaking=null;
const views={
  overview:async()=>{
    const sessions=state.data.sessions,approved=sessions.filter(s=>s.state==='approved'),pending=state.data.reviews.filter(r=>r.state==='pending'),live=state.data.live[0];
    const order=[...approved].sort((a,b)=>a.started-b.started),num=id=>order.findIndex(s=>s.id===id)+1,label=id=>`Session ${String(num(id)).padStart(2,'0')}`;
    const last=order.at(-1),lastBackdrop=last&&records().find(row=>row.properties?.session===last.id&&row.properties?.asset),lastSeen=r=>Math.max(0,...(r.sources||[]).map(s=>num(s.session)));
    const items=records('item').filter(ovCarried).sort((a,b)=>lastSeen(b)-lastSeen(a)||a.name.localeCompare(b.name)).slice(0,4);
    const threads=records('quest').filter(q=>!['done','failed'].includes(q.properties.status)).sort((a,b)=>lastSeen(b)-lastSeen(a)).slice(0,4);
    let gems=last?records().filter(r=>['moment','award','artifact'].includes(r.kind)&&(r.sources||[]).some(s=>s.session===last.id)):[];
    if(!gems.length)gems=records().filter(r=>['moment','award'].includes(r.kind)).sort((a,b)=>lastSeen(b)-lastSeen(a));
    const person=ovFeatured(last,lastSeen),note=ovMyNote();
    const headActions=[live?`<span class="ov-live"><i class="live-dot"></i>Recording now: ${esc(live.title)} · ${live.speakers} opted in</span>`:'',pending.length&&admin()?button(`Review ${pending.length} session${pending.length>1?'s':''}`,'view',{view:'reviews'},'gold'):'',admin()?button('＋ Add session','import-session'):'',admin()&&!live?button(`${ovIcon('play')} Start session`,'record-help',{},'primary'):''].join('');
    const hero=last?`<section class="ov-hero" aria-labelledby="ov-latest">${ovScene(lastBackdrop)}<p class="eyebrow">Latest session</p><h2 id="ov-latest">${esc(last.title)}</h2><ul>${ovBullets(last.recap).map(b=>`<li>${esc(b)}</li>`).join('')}</ul><div class="ov-actions">${'speechSynthesis' in window?`<button type="button" class="button primary" data-action="ov-listen" data-id="${esc(last.id)}">${ovIcon('play')} Listen to recap</button><span class="muted">${Math.max(1,Math.round(String(last.recap||'').split(/\s+/).length/150))} min</span><span class="ov-sep"></span>`:''}<button type="button" class="ov-link" data-action="open-session" data-id="${esc(last.id)}">${ovIcon('book')} Read full recap</button></div><span class="badge ov-corner">${label(last.id)}</span></section>`
      :`<section class="ov-hero">${ovScene()}<p class="eyebrow">A world worth remembering</p><h2>Gather the party. Chronicle keeps the story.</h2><ul><li>Record a session with the Discord bot, or import audio or notes.</li><li>Review and approve what it found.</li><li>Everything lands here, on the player site, and in /ask.</li></ul><div class="ov-actions">${button('How to record a session','record-help',{},'primary')}</div></section>`;
    const inventory=`<section class="ov-card"><div class="ov-card-head"><h2>${ovIcon('bag')}Party inventory</h2></div>${items.length?`<div>${items.map(i=>`<button type="button" class="ov-row" data-action="open-record" data-id="${i.id}"><span class="ov-thumb">${ovIcon(ovItemIcon(i))}</span><span><span class="ov-title">${esc(i.name)}</span><br><span class="ov-subline">${esc(ovItemLine(i))}</span></span><span></span></button>`).join('')}</div>`:`<p class="muted">Nothing tracked yet.</p>`}<div class="ov-foot"><button type="button" class="ov-link" data-action="ov-kind" data-kind="item">View inventory ${ovIcon('arrow')}</button></div></section>`;
    const open=`<section class="ov-card"><div class="ov-card-head"><h2>${ovIcon('bookmark')}Open threads</h2></div>${threads.length?`<div>${threads.map(q=>`<button type="button" class="ov-thread" data-action="open-record" data-id="${q.id}"><span class="ov-box"></span><span>${esc(q.name)}</span><span class="ov-pill ${esc(q.properties.status||'planned')}">${esc(String(q.properties.status||'planned').replace('_',' '))}</span></button>`).join('')}</div>`:`<p class="muted">No open quests right now.</p>`}<div class="ov-foot"><button type="button" class="ov-link" data-action="view" data-view="quests">Open quest log ${ovIcon('arrow')}</button></div></section>`;
    const table=`<section class="ov-card"><div class="ov-card-head"><h2>${ovIcon('scroll')}From the table</h2></div>${gems.length?`<div class="ov-tiles">${gems.slice(0,2).map(g=>`<button type="button" class="ov-tile" data-action="open-record" data-id="${g.id}"><span class="ov-parch${g.kind==='moment'?' seal':''}">${ovIcon('scroll')}</span><span><h3>${esc(g.name)}</h3><span class="ov-subline">${esc(g.kind[0].toUpperCase()+g.kind.slice(1))}${lastSeen(g)?` · Session ${String(lastSeen(g)).padStart(2,'0')}`:''}</span></span></button>`).join('')}</div>`:`<p class="muted">Moments, awards and handouts from your sessions appear here.</p>`}<div class="ov-foot"><button type="button" class="ov-link" data-action="view" data-view="artifacts">View all ${ovIcon('arrow')}</button></div></section>`;
    const profile=person?ovProfile(person,label,num):'';
    const noteCard=state.me.share?'':`<section class="ov-card ov-note"><p class="ov-note-head">${ovIcon('lock')} My note</p><textarea id="ov-note" aria-label="My private note" placeholder="Before next session: who wrote the letter?">${esc(note?.body||'')}</textarea><div class="ov-foot"><button type="button" class="button small" data-action="ov-note-save">Save note</button></div><p class="fine ov-blurb">Saved as a private journal entry only you can see.</p></section>`;
    const ask=state.me.share?'':`<form class="ov-ask" id="ov-ask" role="search"><span class="ov-ask-label">${ovIcon('spark')}Ask Chronicle</span><div class="ov-ask-field"><input id="ov-ask-input" aria-label="Ask a question about the campaign" placeholder="What did we promise Mara?" autocomplete="off"><button class="ov-ask-go" type="submit" aria-label="Ask">${ovIcon('send')}</button></div><p class="ov-ask-hint" id="ov-ask-hint">Searches sessions, transcripts and saved records, then answers with sources. Uses your Codex account.</p></form>`;
    $('#content').innerHTML=`<div class="ov-head"><div><p class="eyebrow">${esc(state.data.campaign.name)}</p><h1>Your adventure, remembered.</h1>${last?`<p class="ov-sub">${ovIcon('arrow')}<a href="#" data-action="open-session" data-id="${esc(last.id)}">${label(last.id)} · ${esc(last.title)}</a></p>`:''}</div><div class="actions">${headActions}</div></div>`+
      `<div class="ov-grid"><div class="ov-stack">${hero}<div class="ov-two">${inventory}${open}</div>${table}</div><div class="ov-stack">${profile}${noteCard}</div></div>${ask}`;
    for(const img of document.querySelectorAll('#content img[data-auth-src]'))fetch(img.dataset.authSrc,{headers:{Authorization:`Bearer ${state.token}`}}).then(r=>r.ok?r.blob():null).then(b=>{if(b)img.src=URL.createObjectURL(b);}).catch(()=>{});
    const form=$('#ov-ask');
    if(form)form.onsubmit=async event=>{event.preventDefault();const question=$('#ov-ask-input').value.trim();if(!question)return;const go=form.querySelector('button');go.disabled=true;$('#ov-ask-hint').textContent='Looking through the archive… this can take a minute.';try{await api(route('ask'),{method:'POST',body:{question}});await navigate('ask');$('#messages')?.lastElementChild?.scrollIntoView({block:'end'});}catch(error){notify(error.message,true);go.disabled=false;$('#ov-ask-hint').textContent='That didn’t work. Check the host terminal, then try again.';}};
  },
  sessions:async()=>{
    $('#content').innerHTML=header('Sessions','The nights that became your campaign.',admin()?button('＋ Add session','import-session',{},'primary'):'')+`<div class="toolbar"><input id="list-search" placeholder="Find a session…" value="${esc(state.query)}"><select id="session-filter"><option value="all">All sessions</option>${['approved','awaiting_review','recording','needs_attention','importing','speaker_review'].map(status=>`<option value="${status}" ${state.filter===status?'selected':''}>${status.replaceAll('_',' ')}</option>`).join('')}</select>${button('Recording guide','record-help')}</div><div class="panel">${state.data.sessions.filter(s=>(state.filter==='all'||s.state===state.filter)&&s.title.toLowerCase().includes(state.query.toLowerCase())).map(sessionRow).join('')||empty('No sessions found','Add a recording or a set of notes to start building your archive.')}</div>`;
  },
  wiki:async()=>{
    const kinds=['all','pc','npc','item','location','faction'];
    $('#content').innerHTML=header('Your world, connected.','The people, places, and things that shape the story.',admin()?button('＋ New entry','new-record',{kind:'npc'},'primary'):'')+`<div class="tabs">${kinds.map(kind=>`<button data-action="filter" data-value="${kind}" class="${state.filter===kind?'active':''}">${kind==='all'?'All entries':kind==='pc'?'Player characters':kind==='npc'?'NPCs':kind[0].toUpperCase()+kind.slice(1)+'s'}</button>`).join('')}</div><div class="toolbar"><input id="list-search" placeholder="Search names, descriptions, or tags…" value="${esc(state.query)}">${badge(records().filter(r=>kinds.includes(r.kind)).length+' entries','neutral')}</div>`+cards(records().filter(r=>kinds.includes(r.kind)&&(state.filter==='all'||r.kind===state.filter)&&match(r)));
  },
  timeline:async()=>{
    const events=records('event').filter(match).sort((a,b)=>{
      const sessionTime=id=>state.data.sessions.find(s=>s.id===id)?.started||0;
      return sessionTime(a.sources[0]?.session)-sessionTime(b.sources[0]?.session)||(a.properties.order??a.properties.offset??0)-(b.properties.order??b.properties.offset??0);
    });
    $('#content').innerHTML=header('The path you’ve taken.','A chronological record of the turning points.',admin()?button('＋ Add event','new-record',{kind:'event'}):'')+`<div class="toolbar"><input id="list-search" value="${esc(state.query)}" placeholder="Find an event or story thread…"></div>`+(events.length?`<div class="timeline-list">${events.map(row=>`<article class="timeline-event"><small>${esc(row.properties.chapter||'STORY EVENT')} · ${time(row.properties.offset||0)}</small><h3>${esc(row.name)}</h3><p>${rich(row.body)}</p><div class="actions">${row.properties.scene?badge(row.properties.scene,'neutral'):''}${button('Open event','open-record',{id:row.id},'small')}</div></article>`).join('')}</div>`:empty('The timeline is waiting','Review a session to turn your adventure into a connected sequence of events.'));
  },
  quests:async()=>{
    const quests=records('quest').filter(q=>(state.filter==='all'||q.properties.status===state.filter)&&match(q));
    $('#content').innerHTML=header('Follow the threads.','Track the promises, mysteries, and unfinished business.',admin()?button('＋ New quest','new-record',{kind:'quest'},'primary'):'')+`<div class="tabs">${['all','planned','in_progress','blocked','done','failed'].map(status=>`<button class="${state.filter===status?'active':''}" data-action="filter" data-value="${status}">${status.replaceAll('_',' ')}</button>`).join('')}</div>`+(quests.length?`<div class="card-grid">${quests.map(q=>`<div class="panel">${questRow(q)}<div class="actions">${button('Open quest ↗','open-record',{id:q.id},'small')}</div></div>`).join('')}</div>`:empty('No quests in this view','Reviewed objectives and manually created quests will appear here.'));
  },
  journals:async()=>{
    const journals=records('journal'),folders=[...new Set(journals.map(r=>r.properties.folder||'Unfiled'))].sort();
    $('#content').innerHTML=header('Room for your own words.','World notes, character thoughts, and plans for the next chapter.',state.me.share?'':button('＋ New journal','new-record',{kind:'journal'},'primary'))+`<div class="toolbar"><input id="list-search" placeholder="Find a note…" value="${esc(state.query)}"><select id="folder-filter"><option value="all">All folders</option>${folders.map(f=>`<option ${state.filter===f?'selected':''}>${esc(f)}</option>`).join('')}</select>${!state.me.share?button('Upload document','import-document'):''}</div><div class="notice green">Journals keep their own permissions. Private entries are available to their author and campaign administrators. Ask Chronicle only receives entries you can read.</div>`+cards(journals.filter(r=>match(r)&&(state.filter==='all'||(r.properties.folder||'Unfiled')===state.filter)));
  },
  artifacts:async()=>{
    const kinds=['all','artifact','moment','award','quote','arc','collection'];
    $('#content').innerHTML=header('Made to be remembered.','Handouts, highlights, character arcs, and collections.',admin()?button('✦ Create artifact','new-artifact',{},'primary')+button('＋ Collection','new-record',{kind:'collection'}):'')+`<div class="tabs">${kinds.map(kind=>`<button class="${state.filter===kind?'active':''}" data-action="filter" data-value="${kind}">${kind==='all'?'All artifacts':kind==='arc'?'Character arcs':kind[0].toUpperCase()+kind.slice(1)+'s'}</button>`).join('')}</div>`+cards(records().filter(r=>kinds.includes(r.kind)&&(state.filter==='all'||r.kind===state.filter)&&match(r)));
  },
  reviews:async()=>{
    const pending=state.data.reviews.filter(r=>r.state==='pending');
    if(!pending.some(r=>r.id===state.review))state.review=pending[0]?.id;
    const review=pending.find(r=>r.id===state.review);
    $('#content').innerHTML=header('A little care makes it canon.','Correct the story before it joins your campaign’s accepted record.')+(review?`<div class="review-layout"><aside class="review-list">${pending.map(r=>`<button class="${r.id===review.id?'active':''}" data-action="select-review" data-id="${r.id}"><strong>${esc(r.payload.title)}</strong><small>${r.payload.facts.length} suggestions · version ${r.version}</small></button>`).join('')}</aside><section class="panel"><form id="review-form"><p class="eyebrow">SESSION REVIEW</p><label>Session title</label><input name="title" value="${esc(review.payload.title)}" required class="full"><label>Recap</label><textarea name="recap" rows="9" class="full">${esc(review.payload.recap)}</textarea>${review.payload.warnings.length?`<div class="notice">${review.payload.warnings.map(esc).join('<br>')}</div>`:''}<div class="section-title"><h2>Suggested changes</h2><span class="fine">Open an entry to edit. Uncheck to reject.</span></div>${review.payload.facts.map((fact,index)=>`<details class="review-fact"><summary><input type="checkbox" name="include-${index}" ${fact.rejected?'':'checked'} aria-label="Include ${esc(fact.name)}"><span>${esc(fact.name)}</span>${badge(fact.kind)}</summary><div class="fact-fields"><label>Name</label><input name="name-${index}" value="${esc(fact.name)}"><label>Description / story beat</label><textarea name="body-${index}">${esc(fact.body)}</textarea><label>Merge into an existing entry (optional)</label><select name="target-${index}"><option value="">Create a new entry / match its exact name</option>${records(fact.kind).map(r=>`<option value="${r.id}" ${fact.target===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select><details><summary class="details-label">Properties, source citations & split tools</summary><label>Properties (JSON)</label><textarea class="code" name="properties-${index}">${esc(JSON.stringify(fact.properties,null,2))}</textarea><label>Tags, separated by commas</label><input name="tags-${index}" value="${esc(fact.tags.join(', '))}"><p class="fine">${fact.sources.length} source transcript segment(s). Citations are retained when you edit.</p>${button('Duplicate to split this suggestion','split-fact',{index},'small')}</details></div></details>`).join('')}<div class="actions"><button class="button primary" type="submit">Save review</button>${button('Approve saved review ✓','approve-review',{id:review.id,version:review.version})}${button('Reject review','reject-review',{id:review.id},'danger')}</div><p class="fine">Save your edits before approval. Approval updates your compendium, quests, highlights, and timeline in one transaction.</p></form></section></div>`:empty('All caught up.','New recordings and imports will appear here after processing. No AI suggestions become accepted campaign facts until you approve them.'));
    if(review)$('#review-form').onsubmit=async event=>{event.preventDefault();try{const data=new FormData(event.target),payload=structuredClone(review.payload);payload.title=data.get('title');payload.recap=data.get('recap');payload.facts.forEach((fact,index)=>{fact.rejected=!data.has(`include-${index}`);fact.name=data.get(`name-${index}`);fact.body=data.get(`body-${index}`);fact.target=data.get(`target-${index}`)||null;fact.properties=JSON.parse(data.get(`properties-${index}`));fact.tags=data.get(`tags-${index}`).split(',').map(t=>t.trim()).filter(Boolean);});await api(route(`reviews/${review.id}`),{method:'PUT',body:{payload,version:review.version}});notify('Review saved. It is ready for approval.');await refresh();}catch(error){notify(error.message,true);}};
  },
  map:async()=>{
    $('#content').innerHTML=header('See how the world fits together.','Wiki links and structured relationships, drawn from the entries you can access.')+`<div class="toolbar"><select id="graph-filter"><option value="all">Every connection</option>${['pc','npc','item','location','faction','quest'].map(kind=>`<option value="${kind}">${kind}</option>`).join('')}</select><input id="graph-search" placeholder="Focus on an entity…">${button('Open selected entry','graph-open',{},'small')}<span class="fine">Drag nodes to arrange · click a node to focus</span></div><div class="graph-wrap"><svg id="graph" viewBox="0 0 1000 650" role="img" aria-label="Campaign relationship map"></svg></div>`;
    state.graph=await api(route('graph'));drawGraph();
  },
  analytics:async()=>{
    const result=await api(route('analytics'));
    $('#content').innerHTML=header('A place for every voice.','Participation patterns across your archived sessions.',admin()?button('Create insight report','new-artifact',{kind:'analysis'}):'')+`<div class="stat-grid">${[['Sessions',result.sessions],['Words spoken',result.totalWords.toLocaleString()],['Voices',result.speakers.length],['Questions asked',result.speakers.reduce((n,s)=>n+s.questions,0)]].map(([label,n])=>`<div class="stat"><div class="label">${label}</div><div class="number">${n}</div></div>`).join('')}</div><div class="two-col"><div class="panel"><h2>Share of the conversation</h2>${result.speakers.map(s=>`<div class="bar-row"><span>${esc(s.speaker)}</span><progress max="1" value="${s.share}"></progress><strong>${(s.share*100).toFixed(1)}%</strong></div>`).join('')||empty('No transcript data','Approve your first session to see participation patterns.')}</div><div class="panel"><h2>Across the story</h2><svg id="trend" class="trend-chart" viewBox="0 0 500 220" aria-label="Words per session trend"></svg><p class="fine">Total transcribed words per session, from earliest to latest.</p></div></div><div class="panel"><h2>Speaker details</h2><div class="table-wrap"><table class="table"><thead><tr><th>Speaker</th><th>Words</th><th>Lines</th><th>Turns</th><th>Questions</th><th>Longest segment</th></tr></thead><tbody>${result.speakers.map(s=>`<tr><td>${esc(s.speaker)}</td><td>${s.words}</td><td>${s.lines}</td><td>${s.turns}</td><td>${s.questions}</td><td>${s.longestTurnWords} words</td></tr>`).join('')}</tbody></table></div><p class="fine">${esc(result.methodology)}</p></div>`;
    const points=result.trend.slice().reverse(),max=Math.max(1,...points.map(p=>p.totalWords));
    $('#trend').innerHTML=`<line x1="30" y1="190" x2="480" y2="190" stroke="#d8dfce"/><polyline fill="none" stroke="#7e9b6d" stroke-width="3" points="${points.map((p,i)=>`${30+i*450/Math.max(points.length-1,1)},${190-p.totalWords/max*160}`).join(' ')}"/>${points.map((p,i)=>`<circle cx="${30+i*450/Math.max(points.length-1,1)}" cy="${190-p.totalWords/max*160}" r="4" fill="#547947"><title>${esc(p.title)}: ${p.totalWords} words</title></circle>`).join('')}`;
  },
  ask:async()=>{
    if(state.me.share){$('#content').innerHTML=header('The archive is yours to explore.','Shared pages provide read-only access to selected campaign content.');return;}
    const messages=await api(route('chat'));
    $('#content').innerHTML=header('A memory for your world.','Ask about the people, promises, and paths in your campaign.',button('Clear conversation','clear-chat'))+`<div class="chat"><div id="messages">${messages.length?messages.map(m=>`<div class="chat-message question">${esc(m.question)}</div><div class="chat-message"><div class="author">✧ CHRONICLE</div><div class="record-body">${rich(m.answer)}</div></div>`).join(''):empty('What would you like to remember?','“What did the innkeeper promise us?” · “Which quests are still open?” · “How did we first meet this character?”')}</div><form id="ask-form" class="chat-compose"><textarea id="question" required maxlength="3000" placeholder="Ask a question about your campaign…"></textarea><div class="actions"><label class="check-label"><input id="creative" type="checkbox"> Creative suggestions, clearly labelled</label><button type="submit" class="button primary">Ask Chronicle ↗</button></div><p class="fine">Uses approved sessions and entries you can access. Codex may be mistaken; check its cited sources.</p></form></div>`;
    $('#ask-form').onsubmit=async event=>{event.preventDefault();const submit=event.target.querySelector('button');submit.disabled=true;submit.textContent='Looking through the archive…';try{await api(route('ask'),{method:'POST',body:{question:$('#question').value,creative:$('#creative').checked}});await views.ask();$('#messages').lastElementChild?.scrollIntoView({behavior:'smooth',block:'end'});}catch(error){notify(error.message,true);}finally{submit.disabled=false;}};
  },
  search:async()=>{
    $('#content').innerHTML=header('Find the thread.',`Searching for “${esc(state.query)}”`)+`<div class="loading">Looking through the archive…</div>`;
    const result=await api(route('search')+'?q='+encodeURIComponent(state.query));
    $('#content').innerHTML=header('Find the thread.',`Results for “${esc(state.query)}”`)+`<h2>Reference entries</h2>${cards(result.entries)}<h2>Transcript excerpts</h2><div class="panel">${result.excerpts.map(c=>`<div class="transcript-line"><time>${time(c.offset)}</time><strong>${esc(c.speaker)}</strong><div class="text">${esc(c.text)}<br>${button('Open session','open-session',{id:c.session},'small')}</div></div>`).join('')||'<p class="muted">No matching transcript excerpts.</p>'}</div>${result.semantic.length?`<h2>Related by meaning</h2><div class="panel">${result.semantic.map(r=>`<p>${esc(r.text)}</p>`).join('')}</div>`:''}`;
  },
  settings:async()=>{
    const settings=state.data.settings,members=await api(route('members')),keys=await api(route('tokens')),shares=await api(route('shares')),discordChannels=admin()?await api(route('discord-channels')).catch(()=>[]):[];
    const channelOptions=discordChannels.map(channel=>`<option value="${esc(channel.id)}" ${settings.rpImageChannel===channel.id?'selected':''}># ${esc(channel.name)}</option>`).join('');
    const pendingImages=(state.data.rpImages||[]); const imageQueue=pendingImages.length?`<section class="panel"><h2>Unassigned RP images</h2><p class="fine">Images captured from the selected Discord channel. Assign each one after the NPC or location is introduced.</p>${pendingImages.map(image=>`<div class="session-row"><img class="avatar" data-auth-src="${route(`images/${image.id}/file`)}" alt=""><div class="row-main"><strong>${esc(image.name)}</strong><small>${esc(image.caption||'No caption')}</small></div>${button('Assign','assign-rp-image',{id:image.id},'small')}</div>`).join('')}</section>`:'';
    $('#content').innerHTML=header('Make room for your table.','Campaign preferences, access, and the tools behind your archive.')+`<div class="settings-grid"><section class="panel"><h2>Campaign preferences</h2><form id="settings-form" class="form-grid"><div><label>Game system</label><input name="system" value="${esc(settings.system)}"></div><div><label>Language (ISO code)</label><input name="language" value="${esc(settings.language)}" placeholder="en, fr, es…"></div><div class="full"><label>Output language</label><input name="outputLanguage" value="${esc(settings.outputLanguage||settings.language)}"><label>Writing tone</label><textarea name="tone" rows="3">${esc(settings.tone)}</textarea><label>Extraction detail</label><select name="extraction">${['essential','balanced','exhaustive'].map(v=>`<option ${settings.extraction===v?'selected':''}>${v}</option>`).join('')}</select><label>Description</label><textarea name="description">${esc(settings.description||'')}</textarea><label>Play-by-post / RP channel</label><select name="rpImageChannel"><option value="">Disabled</option>${channelOptions}</select><p class="fine">Every DM text post in this channel becomes Chronicle source material for review. Every image is captured; assign it to an NPC or location below after it is introduced. Other channels are ignored.</p><label class="check-label"><input type="checkbox" name="retainAudio" ${settings.retainAudio?'checked':''}> Retain raw audio after transcription for playback and downloads</label><label class="check-label"><input type="checkbox" name="postGems" ${settings.postGems?'checked':''}> Post approved recaps and highlights to the campaign Discord channel</label><p class="fine">Retention applies to new processing. Previously deleted audio cannot be restored.</p><button class="button primary" type="submit">Save preferences</button></div></form></section>${imageQueue}<section class="panel"><h2>Campaign cast</h2><p class="fine">Map players, characters, aliases, and Discord user IDs. Cast profiles are distinct from access permissions.</p>${state.data.cast.map(c=>`<div class="session-row"><div class="avatar">${esc(c.player.slice(0,1))}</div><div class="row-main"><h3>${esc(c.player)}</h3><p>${esc(c.character||c.role)}</p></div>${button('Edit','edit-cast',{id:c.id},'small')}</div>`).join('')}${button('＋ Add cast member','new-cast')}<h2>Members & permissions</h2><div class="table-wrap"><table class="table"><thead><tr><th>Member / subject</th><th>Role</th></tr></thead><tbody>${members.map(m=>`<tr><td>${esc(m.display||m.subject)}<br><small>${esc(m.subject)}</small></td><td>${esc(m.role)}</td></tr>`).join('')}</tbody></table></div><div class="actions">${button('Add / update member','new-member')}${button('Issue personal key','new-token')}</div></section><section class="panel"><h2>Access keys</h2><p class="fine">Keys are shown once. Access still follows the member’s current campaign role.</p>${keys.map(k=>`<div class="job-row"><div><strong>${esc(k.label)}</strong><small>${esc(k.subject)} · expires ${date(k.expires)}</small></div>${button('Revoke','revoke-key',{id:k.hash},'small danger')}</div>`).join('')||'<p class="muted">No personal keys issued.</p>'}<h2>Read-only campaign links</h2><p class="fine">Only party reference entries and approved sessions are included. Journals and chat are excluded. Links work only while the host is reachable.</p>${shares.map(s=>`<div class="job-row"><div><strong>${esc(s.label)}</strong><small>Expires ${date(s.expires)}</small></div>${button('Revoke','revoke-share',{id:s.hash},'small danger')}</div>`).join('')}<div class="actions">${button('Create share link','new-share')}</div></section><section class="panel"><h2>Archive tools</h2><p class="fine">Publish the current approved, party-visible archive to the player site after making changes to pictures or entries.</p><div class="actions">${admin()?button('Publish player site','publish-site',{},'primary'):''}${button('Find & replace','replace')}${button('Rebuild semantic index','index')}${button('Export Markdown ZIP','export',{format:'markdown'})}${button('Export Obsidian vault','export',{format:'obsidian'})}${button('Export HTML ZIP','export',{format:'html'})}${button('Restore campaign.json','restore-export')}</div><h2>Connections</h2><p class="fine">Codex and Whisper run on the host. Optional services are configured in .env. No credentials are displayed here.</p><table class="property-table">${[['Semantic search',state.me.capabilities.embeddings],['ComfyUI image generation',state.me.capabilities.images],['Mixed-audio speaker discovery',state.me.capabilities.diarization],['Email delivery',state.me.capabilities.email]].map(([name,enabled])=>`<tr><td>${name}</td><td>${badge(enabled?'configured':'not configured',enabled?'':'neutral')}</td></tr>`).join('')}</table><div class="actions">${button('MCP / Foundry / Obsidian setup','integration-help')}</div></section></div><div class="panel"><h2>Actions hub</h2><p class="fine">Long-running local jobs stay here even if you close the browser.</p>${state.data.jobs.map(job=>`<div class="job-row"><div><strong>${esc(job.kind.replaceAll('_',' '))}</strong><small>${esc(job.error||job.progress||date(job.created))}</small></div>${badge(job.state,job.state==='failed'?'danger':job.state==='done'?'':'pending')}</div>`).join('')||'<p class="muted">No jobs yet.</p>'}</div>`;
    if(state.me.root){const tools=document.createElement('section');tools.className='panel';tools.innerHTML=`<h2>Bulk handouts</h2><p class="fine">Select multiple PNG, JPG, or WebP images. Chronicle creates party-visible handout entries and keeps the original filenames as titles.</p>${button('Import handout images','bulk-handouts',{},'primary')}`;$('#content').querySelector('.settings-grid')?.append(tools);const danger=document.createElement('section');danger.className='panel danger-zone';danger.innerHTML=`<h2>Danger zone</h2><p class="fine">Delete this campaign and its local recordings, entries, access keys, and published site bundle. Your host dashboard key and other campaigns are preserved.</p>${button('Delete campaign','delete-campaign',{},'danger')}`;$('#content').querySelector('.settings-grid')?.append(danger);}
    $('#settings-form').onsubmit=async event=>{event.preventDefault();try{const data=Object.fromEntries(new FormData(event.target));data.retainAudio=event.target.elements.retainAudio.checked;data.postGems=event.target.elements.postGems.checked;await api(route('settings'),{method:'PUT',body:data});notify('Campaign preferences saved.');await refresh();}catch(error){notify(error.message,true);}};
  },
};

function recordKnowledge(row){
  if(!['npc','location','item'].includes(row.kind))return;
  const history=Array.isArray(row.properties?.history)?row.properties.history:[];
  const quotes=row.kind==='npc'?records('quote').filter(quote=>quote.properties?.speaker===row.id):[];
  if(!history.length&&!quotes.length)return;
  const section=document.createElement('section');section.className='panel npc-knowledge';
  section.innerHTML=`<h3>${row.kind==='npc'?'What the party knows':row.kind==='location'?'What the party has learned':'Known history'}</h3>${history.length?`<p class="eyebrow">${row.kind==='npc'?'Important interactions':row.kind==='location'?'Important discoveries':'Important history'}</p><ul>${history.map(item=>`<li>${esc(typeof item==='object'?item.text:item)}</li>`).join('')}</ul>`:''}${quotes.length?`<p class="eyebrow">Notable words</p>${quotes.map(quote=>`<blockquote>“${esc(ovPlain(quote.body))}”${quote.sources?.[0]?.session?` <small>· Session ${esc(quote.sources[0].session)}</small>`:''}</blockquote>`).join('')}`:''}`;
  document.querySelector('#modal-body')?.append(section);
}
async function openRecord(id) {
  const row=records().find(r=>r.id===id)||await api(route('records/'+id));
  const canEdit=!state.me.share&&(admin()||row.author===state.me.subject||['edit','manage'].includes(row.acl[state.me.subject])||row.kind==='pc'&&row.properties.playerSubject===state.me.subject);
  const properties=Object.entries(row.properties).filter(([key])=>!['imagePrompt','asset','gallery'].includes(key));
  const galleryImages=row.kind==='location'?[row.properties.asset,...(Array.isArray(row.properties.gallery)?row.properties.gallery:[])].filter((asset,index,values)=>typeof asset==='string'&&asset&&values.indexOf(asset)===index):[];
  const mainAsset=galleryImages[0];
  const mainImageRoute=mainAsset===row.properties.asset?route(`records/${row.id}/image`):mainAsset?route(`records/${row.id}/gallery/${encodeURIComponent(mainAsset)}`):'';
  const galleryMarkup=galleryImages.length?`<section class="panel record-gallery"><h3>Location gallery</h3><div class="record-gallery-grid">${galleryImages.map((asset,index)=>{const imageRoute=asset===row.properties.asset?route(`records/${row.id}/image`):route(`records/${row.id}/gallery/${encodeURIComponent(asset)}`);return `<button type="button" class="record-gallery-thumb${asset===mainAsset?' selected':''}" data-gallery-thumb aria-label="Show ${esc(row.name)} image ${index+1}"><img class="inline-image" data-auth-src="${imageRoute}" alt="${esc(row.name)} image ${index+1}"></button>`;}).join('')}</div></section>`:'';
  modal(row.name,`<div class="actions">${badge(row.kind)}${badge(row.visibility,row.visibility!=='party'?'private':'')}</div>${mainAsset?'<img id="entry-image" class="inline-image" alt="Campaign artwork">':''}${galleryMarkup}<div class="record-body">${rich(row.body)}</div>${row.kind==='quest'?`<div class="panel"><h3>Objectives</h3>${(row.properties.objectives||[]).map((o,index)=>`<div class="session-row"><div class="row-main"><p>${esc(o.text)}</p></div>${admin()?`<select data-objective="${index}" data-quest="${row.id}">${['planned','in_progress','blocked','done','failed'].map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select>`:badge(o.status)}</div>`).join('')}</div>`:''}${properties.length?`<details><summary class="details-label">Properties & connections</summary><table class="property-table">${properties.map(([key,value])=>`<tr><td>${esc(key)}</td><td>${esc(typeof value==='object'?JSON.stringify(value):value)}</td></tr>`).join('')}</table></details>`:''}<details><summary class="details-label">Sources & history</summary><p class="fine">${row.sources.map(source=>source.session?`Session ${esc(source.session)} ${button('Open','open-session',{id:source.session},'small')}`:esc(JSON.stringify(source))).join('<br>')||'Manually authored entry.'}</p>${admin()?button('Revision history','history',{id:row.id},'small'):''}</details><div class="actions">${canEdit?button('Edit entry','edit-record',{id:row.id},'primary'):''}${button('Download PDF','pdf',{id:row.id})}${button('Download Markdown','markdown',{id:row.id})}${admin()?button('Generate image','generate-image',{id:row.id})+button('Trading card','create-card',{id:row.id})+button('Animated sprite','create-sprite',{id:row.id}):''}${row.properties.asset?button('Download image','download-image',{id:row.id,asset:row.properties.asset}):''}${canEdit?button('Upload image','upload-image',{id:row.id}):''}${row.kind==='location'&&canEdit?button('Upload gallery','upload-gallery',{id:row.id})+button('Add existing image','attach-gallery-image',{id:row.id}):''}${admin()?button('Share / send','deliver',{id:row.id})+button('Merge','merge-entry',{id:row.id})+button('Delete','delete-entry',{id:row.id},'danger'):''}</div>${row.kind==='collection'?`<h3>In this collection</h3>${(row.properties.entries||[]).filter(id=>records().some(r=>r.id===id)).map(id=>button(esc(records().find(r=>r.id===id).name),'open-record',{id})).join('')}`:''}`);
  recordKnowledge(row);
  if(mainImageRoute){const response=await fetch(mainImageRoute,{headers:{Authorization:`Bearer ${state.token}`}});if(response.ok){const url=URL.createObjectURL(await response.blob());$('#entry-image').src=url;$('#modal').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});}}
  for(const image of document.querySelectorAll('#modal-body img[data-auth-src]'))fetch(image.dataset.authSrc,{headers:{Authorization:`Bearer ${state.token}`}}).then(r=>r.ok?r.blob():null).then(blob=>{if(blob){image.src=URL.createObjectURL(blob);image.dataset.loaded='true';}}).catch(()=>{});
  for(const thumb of document.querySelectorAll('#modal-body [data-gallery-thumb]'))thumb.addEventListener('click',()=>{const image=thumb.querySelector('img'),main=$('#entry-image');if(!image?.dataset.loaded||!main)return;main.src=image.src;main.alt=image.alt;document.querySelectorAll('#modal-body [data-gallery-thumb]').forEach(item=>item.classList.toggle('selected',item===thumb));});
}
async function openRecordWithImageTools(id) {
  await openRecord(id);
  if (!admin()) return;
  const row=records().find(record=>record.id===id);
  if (!row) return;
  const actionsBar=[...document.querySelectorAll('#modal-body .actions')].at(-1);
  if (!actionsBar) return;
  const holder=document.createElement('span');holder.innerHTML=button('Use existing image','attach-existing-image',{id},'small');
  actionsBar.append(...holder.childNodes);
}
function editRecord(row={kind:'npc',properties:{},tags:[],sources:[],acl:{},visibility:'party'}) {
  const limited=row.id&&!admin()&&row.kind==='pc'&&row.author!==state.me.subject;
  formModal(row.id?'Edit '+row.name:'New '+row.kind,`<div class="form-grid"><div class="full"><label>Name / title</label><input name="name" required value="${esc(row.name||'')}"></div>${!row.id?`<div><label>Entry type</label><select name="kind">${(admin()?['pc','npc','item','location','faction','quest','event','moment','award','quote','journal','artifact','arc','collection']:['journal']).map(kind=>`<option ${row.kind===kind?'selected':''}>${kind}</option>`).join('')}</select></div>`:''}<div class="full"><label>Description / notes (Markdown and [[wiki links]] supported)</label><textarea name="body" rows="9">${esc(row.body||'')}</textarea></div>${!limited?`<div><label>Visibility</label><select name="visibility">${['party','private','selected'].map(v=>`<option ${row.visibility===v?'selected':''}>${v}</option>`).join('')}</select></div><div><label>Tags, separated by commas</label><input name="tags" value="${esc(row.tags.join(', '))}"></div><div class="full"><label>Folder path (journals)</label><input name="folder" placeholder="Lore / Places" value="${esc(row.properties.folder||'')}"><details><summary class="details-label">Structured properties & per-member permissions</summary><label>Properties (JSON)</label><textarea name="properties" class="code" rows="8">${esc(JSON.stringify(row.properties,null,2))}</textarea><p class="fine">Use aliases: [], objectives: [{text,status}], playerSubject for character ownership, or entry IDs for relationships. Collections use entries: [entry IDs].</p><label>Journal access overrides (JSON)</label><textarea name="acl" class="code">${esc(JSON.stringify(row.acl,null,2))}</textarea><p class="fine">Example: {"DISCORD_USER_ID":"view"}. Roles: view, edit, manage. Private journals remain visible to their author and campaign administrators.</p></details></div>`:''}</div>`,async data=>{
    const properties=limited?row.properties:JSON.parse(data.get('properties')||'{}');if(!limited&&data.get('folder'))properties.folder=data.get('folder');
    await api(route(`records${row.id?'/'+row.id:''}`),{method:row.id?'PUT':'POST',body:{...row,kind:row.id?row.kind:data.get('kind'),name:data.get('name'),body:data.get('body'),visibility:limited?row.visibility:data.get('visibility'),tags:limited?row.tags:data.get('tags').split(',').map(t=>t.trim()).filter(Boolean),properties,acl:limited?row.acl:JSON.parse(data.get('acl')||'{}')}});notify('Entry saved.');
  });
}
async function openSession(id) {
  const result=await api(route(`sessions/${id}/transcript`)),session=result.session;
  const speakers=[...new Set(result.chunks.map(c=>c.speaker))];
  modal(session.title,`<div class="actions">${badge(session.state)}<span class="fine">${date(session.started)} · ${session.id}</span></div>${session.recap?`<h3>Session recap</h3><div class="record-body">${rich(session.recap)}</div>`:''}<div class="actions">${admin()?button('Generate / retry review','process-session',{id}):''}${admin()?button('Discover speakers','discover',{id}):''}${admin()?button('Map speaker labels','map-speakers',{id}):''}${button('Download transcript','transcript',{id})}${admin()?button('Edit session details','edit-session',{id}):''}${admin()?button('Delete session','delete-session',{id},'danger'):''}</div><h3>Transcript</h3><p class="fine">${result.chunks.filter(c=>c.text).length} segments · ${speakers.length} labels. First 200 segments displayed; download for the full text.</p>${result.chunks.filter(c=>c.text||c.state!=='done').slice(0,200).map(c=>`<div class="transcript-line"><time>${time(c.offset)}</time><strong>${esc(c.speaker)}</strong><div class="text">${esc(c.text)||badge(c.state,'neutral')}${admin()&&c.text?button('Edit','edit-chunk',{session:id,chunk:c.id},'small'):''}${c.audioAvailable?button('Audio','play-audio',{session:id,chunk:c.id},'small'):''}</div></div>`).join('')||empty('No transcript yet','Upload a track, then process the session.')}`);
}
async function openSessionWithBackdrop(id) {
  await openSession(id);
  const backdrop=records().find(row=>row.properties?.session===id&&row.properties?.asset);
  if (backdrop) {
    const panel=document.createElement('section');panel.className='panel';panel.innerHTML=`<h3>Session backdrop</h3><img id="session-backdrop" class="inline-image" alt="${esc(backdrop.name)}">`;
    $('#modal-body')?.prepend(panel);
    const response=await fetch(route(`records/${backdrop.id}/image`),{headers:{Authorization:`Bearer ${state.token}`} });
    if(response.ok){const url=URL.createObjectURL(await response.blob());$('#session-backdrop').src=url;$('#modal').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});}
  }
  if (!admin()) return;
  const actionsBar=document.querySelector('#modal-body .actions');
  if (!actionsBar) return;
  const holder=document.createElement('span');holder.innerHTML=button('Backdrop prompt','backdrop-prompt',{id})+button('Upload backdrop','upload-backdrop',{id});
  actionsBar.append(...holder.childNodes);
}
function drawGraph() {
  const svg=$('#graph');if(!svg)return;let nodes=state.graph.nodes.slice(0,150),edges=state.graph.edges;
  const linkMode=$('#graph-edge-type')?.value||'all',sessionMode=$('#graph-session')?.value||'all';
  if(linkMode==='wikilink')edges=edges.filter(e=>e.kind==='wikilink');if(linkMode==='properties')edges=edges.filter(e=>e.kind!=='wikilink');
  if(sessionMode!=='all')nodes=nodes.filter(n=>!n.sessions?.length||n.sessions.includes(sessionMode));
  const filter=$('#graph-filter')?.value||'all',query=$('#graph-search')?.value.toLowerCase()||'';
  if(filter!=='all'){const focus=new Set(nodes.filter(n=>n.kind===filter).map(n=>n.id));const neighbors=new Set(edges.filter(e=>focus.has(e.from)||focus.has(e.to)).flatMap(e=>[e.from,e.to]));nodes=nodes.filter(n=>focus.has(n.id)||neighbors.has(n.id));}
  const ids=new Set(nodes.map(n=>n.id));edges=edges.filter(e=>ids.has(e.from)&&ids.has(e.to));
  const colors={pc:'#5b8867',npc:'#8ca487',location:'#b3a571',item:'#bda773',faction:'#93889d',quest:'#ad9871',event:'#8294a5',journal:'#aaabb0'};
  nodes.forEach((n,i)=>{n.x??=500+Math.cos(i*2*Math.PI/Math.max(nodes.length,1))*Math.min(380,130+nodes.length*5);n.y??=310+Math.sin(i*2*Math.PI/Math.max(nodes.length,1))*Math.min(240,100+nodes.length*3);});
  const layout=$('#graph-layout')?.value||'circle';
  if(layout==='grid'){const cols=Math.max(1,Math.ceil(Math.sqrt(nodes.length*1.5))),rows=Math.ceil(nodes.length/cols);nodes.forEach((n,i)=>{n.x=60+(i%cols)*880/Math.max(1,cols-1);n.y=50+Math.floor(i/cols)*530/Math.max(1,rows-1);});}
  if(layout==='force')for(let iteration=0;iteration<55;iteration++){
    for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++){const a=nodes[i],b=nodes[j],dx=a.x-b.x,dy=a.y-b.y,d=Math.max(25,Math.hypot(dx,dy)),force=110/d;a.x+=dx/d*force;a.y+=dy/d*force;b.x-=dx/d*force;b.y-=dy/d*force;}
    for(const edge of edges){const a=nodes.find(n=>n.id===edge.from),b=nodes.find(n=>n.id===edge.to);if(a&&b){const dx=b.x-a.x,dy=b.y-a.y;a.x+=dx*0.008;a.y+=dy*0.008;b.x-=dx*0.008;b.y-=dy*0.008;}}
    nodes.forEach(n=>{n.x=Math.max(50,Math.min(950,n.x));n.y=Math.max(45,Math.min(590,n.y));});
  }
  const nodeMap=new Map(nodes.map(n=>[n.id,n]));
  const focus=state.graph.focus || nodes.find(n=>query&&n.name.toLowerCase().includes(query))?.id;
  const related=new Set(focus?[focus,...edges.filter(e=>e.from===focus||e.to===focus).flatMap(e=>[e.from,e.to])]:nodes.map(n=>n.id));
  svg.innerHTML=edges.map(e=>`<line class="graph-edge ${focus&&!(e.from===focus||e.to===focus)?'faded':''}" x1="${nodeMap.get(e.from).x}" y1="${nodeMap.get(e.from).y}" x2="${nodeMap.get(e.to).x}" y2="${nodeMap.get(e.to).y}"><title>${esc(e.kind)}</title></line>`).join('')+nodes.map(n=>`<g class="graph-node ${!related.has(n.id)?'faded':''}" data-node="${n.id}" transform="translate(${n.x},${n.y})"><circle r="${n.kind==='pc'?24:18}" fill="${colors[n.kind]||'#8eaa82'}"/><text y="37">${esc(n.name.slice(0,26))}</text><title>${esc(n.name)} · ${esc(n.kind)}</title></g>`).join('');
  if(!nodes.length)svg.innerHTML='<text x="500" y="310" text-anchor="middle" fill="#8f9b84" font-size="15">Add [[wiki links]] or relationship IDs to connect your world.</text>';
  svg.onpointerdown=event=>{const el=event.target.closest('[data-node]');if(!el)return;const node=nodeMap.get(el.dataset.node);state.graph.focus=node.id;svg.setPointerCapture(event.pointerId);svg.onpointermove=e=>{const point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const pos=point.matrixTransform(svg.getScreenCTM().inverse());node.x=Math.max(35,Math.min(965,pos.x));node.y=Math.max(35,Math.min(600,pos.y));drawGraph();};svg.onpointerup=()=>{svg.onpointermove=null;drawGraph();};};
}

const actions={
  close:()=>$('#modal').close(),view:d=>navigate(d.view),filter:async d=>{state.filter=d.value;await render();},'open-record':d=>openRecordWithImageTools(d.id),'edit-record':d=>editRecord(records().find(r=>r.id===d.id)),'new-record':d=>editRecord({kind:d.kind,properties:{},tags:[],sources:[],acl:{},visibility:d.kind==='journal'?'private':'party'}),'open-session':d=>openSessionWithBackdrop(d.id),
  'create-campaign':()=>formModal('A new world to remember.',`<label>Campaign name</label><input name="name" required placeholder="The name of your adventure">`,async data=>{const campaign=await api('/api/campaigns',{method:'POST',body:{name:data.get('name')}});state.campaign=campaign.id;await boot();},'Create campaign'),
  'delete-campaign':async()=>{const name=state.data.campaign.name;if(!confirm(`Permanently delete “${name}” and all of its stored data? Your host key and other campaigns will remain.`))return;const typed=prompt(`Type the exact campaign name to confirm deletion:\n${name}`);if(typed===null)return;if(typed!==name){notify('Campaign name did not match.',true);return;}await api('/api/campaigns/'+state.campaign,{method:'DELETE',body:{name:typed}});state.campaign='';state.data=null;notify('Campaign deleted.');await boot();},
  'backdrop-prompt':async d=>{const session=state.data.sessions.find(row=>row.id===d.id)||{};const promptText=`Act as an art director for a fantasy tabletop campaign. Analyze the session recap below and distill it into the strongest visual themes rather than repeating the plot. Identify the dominant setting, mood, conflict, symbolic motifs, memorable environmental details, and the single moment or image that best represents the session. Then create one polished image-generation prompt from that analysis. Prioritize atmosphere and visual storytelling over literal scene coverage. Do not include names, readable text, logos, borders, character portraits, or UI elements unless a non-readable silhouette is artistically useful.\n\nSession title: ${session.title||'Untitled session'}\n\nSession recap:\n${session.recap||'Use the session title as the starting concept.'}\n\nOutput only the final image prompt after your internal analysis. Use a wide horizontal 16:9 composition for a full-width campaign recap card. Keep important details inside the central safe area, leave the left third darker and uncluttered for readable recap text, and place the main focal point toward the center-right. Use cinematic fantasy lighting and avoid important details near the edges.`;modal('Backdrop prompt',`<p class="fine">This asks your GPT to extract the session’s visual themes and turn them into one focused image prompt. Copy it into your GPT image conversation, download the result, then use <strong>Upload backdrop</strong> here.</p><textarea id="backdrop-prompt-text" rows="16">${esc(promptText)}</textarea><div class="actions">${button('Copy prompt','copy-backdrop-prompt')}</div>`);},
  'copy-backdrop-prompt':async()=>{const value=$('#backdrop-prompt-text')?.value||'';await navigator.clipboard.writeText(value);notify('Backdrop prompt copied.');},
  'upload-backdrop':d=>formModal('Upload session backdrop.',`<p class="fine">Download the image from your GPT conversation first, then select it here. PNG, JPG, or WebP up to 10 MB.</p><input name="file" type="file" accept=".png,.jpg,.jpeg,.webp" required>`,async data=>{const file=data.get('file');const session=state.data.sessions.find(row=>row.id===d.id);const row=await api(route('records'),{method:'POST',body:{kind:'artifact',name:`${session.title} backdrop`,body:`Backdrop artwork for ${session.title}.`,visibility:'party',properties:{folder:'Session backdrops',session:d.id}}});await api(route(`records/${row.id}/image`),{method:'PUT',headers:{'X-File-Name':file.name},body:file});notify('Session backdrop uploaded.');},'Upload backdrop'),
  'attach-existing-image':d=>{const target=records().find(row=>row.id===d.id),sources=records().filter(row=>row.id!==d.id&&row.properties?.asset);if(!sources.length){notify('No handout or artwork images are available yet.',true);return;}formModal(`Use an image for ${target.name}.`,`<p class="fine">Choose an existing handout or artwork image. This reuses the file; it does not create a duplicate.</p><label>Image</label><select name="source">${sources.map(row=>`<option value="${row.id}">${esc(row.name)} · ${esc(row.kind)}</option>`).join('')}</select>`,async data=>{const source=sources.find(row=>row.id===data.get('source'));await api(route(`records/${target.id}`),{method:'PUT',body:{...target,properties:{...target.properties,asset:source.properties.asset},version:target.version}});notify(`Image attached to ${target.name}.`);},'Attach image');},
  'bulk-handouts':()=>formModal('Import handout images.',`<p class="fine">Choose the images you already have from this campaign. Each file becomes a party-visible handout entry. PNG, JPG, and WebP up to 10 MB each.</p><input name="files" type="file" accept=".png,.jpg,.jpeg,.webp" multiple required>`,async data=>{const files=data.getAll('files').filter(file=>file instanceof File&&file.size);let imported=0,failed=0;for(const file of files){try{const name=file.name.replace(/\.[^.]+$/,'').replace(/[_-]+/g,' ').trim()||'Untitled handout';const row=await api(route('records'),{method:'POST',body:{kind:'artifact',name,body:`Imported handout: ${file.name}`,visibility:'party',properties:{folder:'Handouts'}}});await api(route(`records/${row.id}/image`),{method:'PUT',headers:{'X-File-Name':file.name},body:file});imported++;}catch{failed++;}}if(failed)notify(`Imported ${imported} handout(s); ${failed} failed.`,true);else notify(`Imported ${imported} handout(s).`);},'Import images'),
  'record-help':()=>modal('Gather your party.',`<p>Run the bot on your computer with <code>npm start</code>, then join your Discord voice channel.</p><ol><li>Create a campaign in its text channel with <code>/campaign create</code>.</li><li>Run <code>/start</code> (or <code>/session start</code>) and choose the voice channel.</li><li>Each participant runs <code>/consent allow:true</code> before their voice is saved.</li><li>Run <code>/end</code> to finish. Open the review queue here to correct and approve the session.</li></ol><div class="notice">Whisper transcribes locally. Codex receives transcript text and uses your account limits. Your computer must stay on. Everyone should know recording is active.</div>`),
  'import-session':()=>{
    formModal('Bring a session into the archive.',`<label>Session title</label><input name="title" required placeholder="Session 1: A knock at the door"><label>Session date</label><input type="datetime-local" name="date"><label>Notes / existing transcript (optional)</label><textarea name="notes" rows="6" placeholder="Paste the session notes here…"></textarea><div class="upload-area"><strong>Or add audio tracks</strong><p class="fine">One mixed recording, or aligned files named for their speakers. Up to 2 GB per track.</p><input name="audio" type="file" multiple accept="audio/*,.webm,.mp4,.opus"><label class="check-label"><input name="consent" type="checkbox"> Everyone in these recordings agreed to transcription and AI processing.</label><label class="check-label"><input name="discover" type="checkbox"> Run optional local speaker discovery on one mixed file before transcription.</label></div>`,async data=>{
      const files=data.getAll('audio').filter(f=>f.size);if(files.length&&!data.has('consent'))throw new Error('Confirm recording consent before importing audio.');if(!files.length&&!String(data.get('notes')).trim())throw new Error('Add notes or an audio file.');
      const session=await api(route('sessions'),{method:'POST',body:{title:data.get('title'),date:data.get('date')||undefined,notes:data.get('notes')}});
      for(const file of files)await api(route(`sessions/${session.id}/audio`)+`?consent=true&label=${encodeURIComponent(files.length>1?file.name.replace(/\.[^.]+$/,''):'Uploaded recording (speakers unknown)')}`,{method:'PUT',headers:{'X-File-Name':file.name},body:file});
      await api(route(`sessions/${session.id}/${data.has('discover')?'discover':'process'}`),{method:'POST',body:{}});notify('Session imported. Watch the Actions hub for progress.');
    },'Import and process');
  },
  'process-session':async d=>{await api(route(`sessions/${d.id}/process`),{method:'POST',body:{}});notify('Processing queued. Open the review queue when ready.');$('#modal').close();await refresh();},
  'discover':async d=>{if(!confirm('Run local speaker discovery on the uploaded mixed recording? This requires pyannote.audio and model access configured on the host.'))return;await api(route(`sessions/${d.id}/discover`),{method:'POST',body:{}});notify('Speaker discovery queued. Map labels once it finishes.');$('#modal').close();},
  'map-speakers':async d=>{const result=await api(route(`sessions/${d.id}/transcript`));const labels=[...new Set(result.chunks.map(c=>c.speaker))];formModal('Who is speaking?',labels.map((label,index)=>`<label>${esc(label)}</label><input name="label-${index}" value="${esc(label)}" list="cast-labels">`).join('')+`<datalist id="cast-labels">${state.data.cast.map(c=>`<option>${esc(c.character||c.player)}</option>`).join('')}</datalist>`,async data=>{const mapping=Object.fromEntries(labels.map((label,index)=>[label,data.get(`label-${index}`)]));await api(route(`sessions/${d.id}/map-speakers`),{method:'POST',body:{mapping}});await api(route(`sessions/${d.id}/process`),{method:'POST',body:{}});notify('Speakers mapped; transcription and review queued.');});},
  'edit-session':d=>{const session=state.data.sessions.find(s=>s.id===d.id);formModal('Edit session details',`<label>Title</label><input name="title" required value="${esc(session.title)}"><label>Date</label><input type="datetime-local" name="date" value="${new Date(session.started-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)}">`,async data=>{await api(route('sessions/'+d.id),{method:'PUT',body:Object.fromEntries(data)});notify('Session updated.');});},
  'delete-session':async d=>{if(!confirm('Permanently delete this session and its retained audio? Already posted Discord messages and exported files remain.'))return;await api(route('sessions/'+d.id),{method:'DELETE'});$('#modal').close();notify('Session deleted.');await refresh();},
  'edit-chunk':async d=>{const result=await api(route(`sessions/${d.session}/transcript`)),chunk=result.chunks.find(c=>c.id===d.chunk);formModal('Correct transcript',`<label>Speaker</label><input name="speaker" value="${esc(chunk.speaker)}"><label>Transcript text</label><textarea name="text" rows="7">${esc(chunk.text)}</textarea>`,async data=>{await api(route(`sessions/${d.session}/chunk`),{method:'PUT',body:{id:chunk.id,before:chunk.text,text:data.get('text'),speaker:data.get('speaker')}});notify('Transcript corrected. Existing approved reference entries are not rewritten automatically.');});},
  'play-audio':async d=>{const response=await fetch(route(`sessions/${d.session}/audio`)+`?chunk=${d.chunk}`,{headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok)throw new Error((await response.json()).error);const url=URL.createObjectURL(await response.blob());modal('Retained session audio','<audio id="audio-player" controls></audio>');$('#audio-player').src=url;$('#audio-player').play().catch(()=>{});$('#modal').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});},
  'transcript':async d=>{const result=await api(route(`sessions/${d.id}/transcript`));const url=URL.createObjectURL(new Blob([result.markdown],{type:'text/markdown'})),a=document.createElement('a');a.href=url;a.download=d.id+'-transcript.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},
  'select-review':async d=>{state.review=d.id;await render();},
  'approve-review':async d=>{if(!confirm('Approve the saved version of this review and update the campaign record? Unsaved edits will not be included.'))return;await api(route(`reviews/${d.id}/approve`),{method:'POST',body:{version:Number(d.version)}});notify('Session approved. Your campaign record is updated.');await refresh();},
  'reject-review':async d=>{if(!confirm('Reject this entire review? Source transcripts will be kept.'))return;await api(route(`reviews/${d.id}/reject`),{method:'POST',body:{}});notify('Review rejected.');await refresh();},
  'split-fact':async d=>{if(!confirm('Duplicate this saved suggestion so you can give each part a separate name and description? Save your current edits first.'))return;const review=state.data.reviews.find(r=>r.id===state.review),payload=structuredClone(review.payload);payload.facts.push({...structuredClone(payload.facts[Number(d.index)]),name:payload.facts[Number(d.index)].name+' (split)',target:null});await api(route(`reviews/${review.id}`),{method:'PUT',body:{payload,version:review.version}});await refresh();},
  'pdf':d=>download(route(`records/${d.id}/pdf`),'chronicle-handout.pdf'),
  'markdown':d=>{const row=records().find(r=>r.id===d.id),url=URL.createObjectURL(new Blob([`# ${row.name}\n\n${row.body}`],{type:'text/markdown'})),a=document.createElement('a');a.href=url;a.download='chronicle-entry.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},
  'new-artifact':d=>formModal('Make something to keep.',`<label>Artifact type</label><select name="kind">${['handout','card','questlog','arc','analysis','journal'].map(kind=>`<option ${d.kind===kind?'selected':''}>${kind}</option>`).join('')}</select><label>Session (optional)</label><select name="session"><option value="">Campaign-wide</option>${state.data.sessions.filter(s=>s.state==='approved').map(s=>`<option value="${s.id}">${esc(s.title)}</option>`).join('')}</select><label>Character / reference entry (optional)</label><select name="entity"><option value="">None</option>${records().filter(r=>['pc','npc','item','location','faction'].includes(r.kind)).map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select><label>Additional instructions</label><textarea name="instructions" rows="3"></textarea><p class="fine">Character arc suggestions are saved privately for review. Creative journal drafts are artifacts and do not overwrite journals.</p>`,async data=>{await api(route('artifacts'),{method:'POST',body:Object.fromEntries([...data].filter(([k,v])=>v))});notify('Artifact queued. Watch the Actions hub for completion.');},'Generate artifact'),
  'import-document':()=>formModal('Add a document to your journals.',`<label>Title</label><input name="title"><label>Folder path</label><input name="folder"><div class="upload-area"><input name="file" type="file" accept=".pdf,.docx,.txt,.md" required><p class="fine">PDF, Word, text, or Markdown. Up to 10 MB. Imported entries start private.</p></div>`,async data=>{const file=data.get('file');await api(route('import-document')+`?title=${encodeURIComponent(data.get('title')||file.name)}&folder=${encodeURIComponent(data.get('folder'))}`,{method:'POST',headers:{'X-File-Name':file.name},body:file});notify('Document imported as a private journal.');}),
  'new-cast':()=>editCast(), 'edit-cast':d=>editCast(state.data.cast.find(c=>c.id===d.id)),
  'new-member':()=>formModal('Campaign access',`<label>Member subject / Discord user ID</label><input name="subject" required><label>Display name</label><input name="display"><label>Role</label><select name="role"><option>player</option><option>admin</option><option>owner</option></select><p class="fine">Only owners can appoint administrators or owners. A player can read party content and write their own journals.</p>`,async data=>{await api(route('members'),{method:'POST',body:Object.fromEntries(data)});notify('Membership updated.');}),
  'new-token':async()=>{const members=await api(route('members'));formModal('A personal key for your player.',`<label>Member</label><select name="subject">${members.map(m=>`<option value="${esc(m.subject)}">${esc(m.display||m.subject)} (${m.role})</option>`).join('')}</select><label>Key label</label><input name="label" value="Player dashboard"><label>Expires in days</label><input name="days" type="number" min="1" max="365" value="30"><label class="check-label"><input name="write" type="checkbox" checked> Allow writing within this member’s permissions</label>`,async data=>{const result=await api(route('tokens'),{method:'POST',body:{subject:data.get('subject'),label:data.get('label'),days:Number(data.get('days')),scopes:data.has('write')?['read','write']:['read']}});setTimeout(()=>modal('Your personal key',`<p>Copy this once and send it privately to the intended player. The host must be reachable from their computer.</p><pre class="code">${esc(location.origin+'/#token='+result.token)}</pre><p class="fine">This key follows the chosen member’s permissions. Revoke it at any time in Settings.</p>`),100);});},
  'new-share':()=>formModal('Share an accepted story.',`<label>Link label</label><input name="label" value="Campaign story"><label>Expires in days</label><input name="days" type="number" min="1" max="365" value="30"><p class="fine">Includes party reference entries and approved sessions; excludes all journals, private entries, source audio, and chat.</p>`,async data=>{const result=await api(route('shares'),{method:'POST',body:{label:data.get('label'),days:Number(data.get('days'))}});setTimeout(()=>modal('Read-only campaign link',`<p>This is a private access link, not a public hosted website. It works while your Chronicle host is reachable.</p><pre class="code">${esc(location.origin+'/#token='+result.token)}</pre>`),100);}),
  'revoke-key':async d=>{await api(route('tokens/'+d.id),{method:'DELETE'});notify('Access key revoked.');await refresh();},'revoke-share':async d=>{await api(route('shares/'+d.id),{method:'DELETE'});notify('Share link revoked.');await refresh();},
  'replace':()=>{formModal('Find & replace',`<label>Find literal text</label><input name="find" required><label>Replace with</label><input name="replacement"><label class="check-label"><input name="apply" type="checkbox"> Apply immediately (leave unchecked to preview)</label><div class="notice">This changes entry names/descriptions and transcript text. It does not interpret regular expressions or rewrite existing recaps. Review the preview before applying.</div>`,async data=>{const result=await api(route('replace'),{method:'POST',body:{find:data.get('find'),replacement:data.get('replacement'),apply:data.has('apply')}});setTimeout(()=>modal(data.has('apply')?'Replacement complete':'Replacement preview',`<p>${result.length} affected entry/segment(s).</p>${result.slice(0,40).map(c=>`<div class="panel"><small>${esc(c.type)}</small><p><del>${esc(c.before.slice(0,300))}</del></p><p>${esc(c.after.slice(0,300))}</p></div>`).join('')}`),100);});},
  'publish-site':async()=>{if(!confirm('Publish the current approved, party-visible campaign to the player site?'))return;const result=await api(route('publish'),{method:'POST',body:{}});notify(result.pushed?`Player site published: ${result.sessions} approved session${result.sessions===1?'':'s'} and ${result.records} entr${result.records===1?'y':'ies'}. GitHub Pages may take about a minute to refresh.`:'Site files written locally. Enable SITE_GIT_PUSH=1 to push them to GitHub Pages.');},
  'index':async()=>{await api(route('index'),{method:'POST',body:{}});notify('Local semantic indexing queued.');await refresh();},'export':d=>download(route('export')+'?format='+encodeURIComponent(d.format),'chronicle-'+d.format+'.zip'),
  'clear-chat':async()=>{if(!confirm('Clear your saved conversation for this campaign?'))return;await api(route('chat'),{method:'DELETE'});await render();},
  'merge-entry':d=>{const row=records().find(r=>r.id===d.id);formModal('Merge duplicate entries',`<p>Merge <strong>${esc(row.name)}</strong> into another entry of the same type. Descriptions, aliases and citations are retained, and wiki links are repointed.</p><label>Keep this entry as the target</label><select name="target" required>${records(row.kind).filter(r=>r.id!==row.id&&r.visibility===row.visibility).map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select>`,async data=>{if(!data.get('target'))throw new Error('Create another matching entry before merging.');await api(route('records/merge'),{method:'POST',body:{source:row.id,target:data.get('target')}});notify('Entries merged; earlier versions remain in history.');},'Merge entries');},
  'delete-entry':async d=>{if(!confirm('Delete this reference entry? Earlier text remains in revision history for administrators.'))return;await api(route('records/'+d.id),{method:'DELETE'});$('#modal').close();notify('Entry deleted.');await refresh();},
  'restore-export':()=>formModal('Restore an exported campaign',`<p>Choose the <code>campaign.json</code> from a Chronicle export. This adds copied sessions and entries to the current campaign; it does not restore access keys or member permissions.</p><input type="file" name="file" accept=".json" required><label class="check-label"><input type="checkbox" name="confirm" required> I want to import these entries into this campaign.</label><p class="fine">To preserve exported artwork, copy the export’s assets folder into the host’s data/assets folder separately.</p>`,async data=>{const file=data.get('file');const result=await api(route('restore-export'),{method:'POST',body:{confirm:true,data:JSON.parse(await file.text())}});notify(`Imported ${result.sessions} session(s) and ${result.entries} entries.`);},'Import archive'),
  'history':async d=>{const rows=await api(route(`records/${d.id}/history`));modal('Revision history',rows.map(row=>`<div class="panel"><h3>${esc(row.payload.name)}</h3><p class="fine">${date(row.created)} · version ${row.payload.version}</p><p>${esc(row.payload.body).slice(0,400)}</p>${button('Restore this version','restore',{revision:row.id})}</div>`).join('')||empty('No earlier revisions','Earlier versions appear here after an entry is edited.'));},
  'restore':async d=>{if(!confirm('Restore this version? The current content will be kept in history.'))return;await api(route('records/restore'),{method:'POST',body:{revision:Number(d.revision)}});$('#modal').close();notify('Earlier version restored.');await refresh();},
  'download-image':d=>download(route(`records/${d.id}/image`),'chronicle-'+(d.asset||'art.png')),
  'create-card':d=>formModal('A card from your campaign.',`<label>Theme</label><select name="theme"><option>parchment</option><option>night</option><option>azure</option><option>verdant</option><option>infernal</option></select><label>Subtitle</label><input name="subtitle" placeholder="Class · species · level, or item type / rarity"><label>Short description</label><textarea name="body" rows="4">${esc(records().find(r=>r.id===d.id).body.slice(0,400))}</textarea><label>Up to six stat labels and values (JSON)</label><textarea name="stats" class="code">[]</textarea><div class="form-grid"><div><label>Portrait zoom (1–3)</label><input name="zoom" type="number" min="1" max="3" step="0.1" value="1"></div><div><label>Horizontal / vertical position (0–1)</label><input name="panX" type="number" min="0" max="1" step="0.1" value="0.5"><input name="panY" type="number" min="0" max="1" step="0.1" value="0.5"></div></div><p class="fine">Uses the existing portrait and local Pillow rendering. Creates a high-resolution PNG artifact.</p>`,async data=>{await api(route('cards'),{method:'POST',body:{entry:d.id,theme:data.get('theme'),body:data.get('body'),subtitle:data.get('subtitle'),stats:JSON.parse(data.get('stats')),zoom:Number(data.get('zoom')),panX:Number(data.get('panX')),panY:Number(data.get('panY'))}});notify('Trading card queued. Open Artifacts when ready.');},'Create card'),
  'create-sprite':d=>formModal('A little life for your character.',`<label>Animation</label><select name="animation">${['victory','hello','attack','cast','laugh','defeat','idle','angry'].map(v=>`<option>${v}</option>`).join('')}</select><label>Up to five context tags</label><input name="tags" placeholder="scimitar, owl, desert"><div class="notice">Requires local ComfyUI and an existing portrait. The model creates a sprite sheet; Chronicle assembles it into a looping GIF. Review alignment and consistency before sharing.</div>`,async data=>{await api(route('sprites'),{method:'POST',body:{entry:d.id,animation:data.get('animation'),tags:data.get('tags').split(',').map(v=>v.trim()).filter(Boolean).slice(0,5)}});notify('Sprite generation queued. Open Artifacts when ready.');},'Generate sprite'),
  'generate-image':d=>formModal('Create campaign artwork.',`<label>Image type</label><select name="type"><option>portrait</option><option>card</option><option>sprite</option></select><label>Style</label><input name="style" value="Fantasy illustration, rich natural textures"><label>Additional visual details</label><textarea name="prompt"></textarea><p class="fine">Uses a local ComfyUI server and configured checkpoint. Sprites are still images, not animated or guaranteed transparent. Review the result before sharing.</p>`,async data=>{await api(route('images'),{method:'POST',body:{entry:d.id,...Object.fromEntries(data)}});notify('Image generation queued on the local host.');},'Generate image'),
  'upload-image':d=>formModal('Attach an image.',`<input type="file" name="file" accept=".png,.jpg,.webp,.gif" required><p class="fine">PNG, JPG, WebP or GIF, up to 10 MB.</p>`,async data=>{const file=data.get('file');await api(route(`records/${d.id}/image`),{method:'PUT',headers:{'X-File-Name':file.name},body:file});notify('Image attached.');}),
  'upload-gallery':d=>formModal('Add location gallery images.',`<p class="fine">Choose one or more images. The first image becomes the location’s primary image if it does not have one yet.</p><input type="file" name="files" accept=".png,.jpg,.jpeg,.webp,.gif" multiple required>`,async data=>{const files=data.getAll('files').filter(file=>file instanceof File&&file.size);for(const file of files)await api(route(`records/${d.id}/gallery`),{method:'PUT',headers:{'X-File-Name':file.name},body:file});notify(`${files.length} location image${files.length===1?'':'s'} added.`);},'Add images'),
  'attach-gallery-image':d=>{const target=records().find(row=>row.id===d.id),sources=records().filter(row=>row.id!==d.id&&row.properties?.asset);if(!sources.length){notify('No existing artwork images are available yet.',true);return;}formModal(`Add an existing image to ${target.name}.`,`<p class="fine">This reuses the existing file and does not create a duplicate.</p><label>Image</label><select name="source">${sources.map(row=>`<option value="${row.id}">${esc(row.name)} · ${esc(row.kind)}</option>`).join('')}</select>`,async data=>{const source=sources.find(row=>row.id===data.get('source'));const gallery=[...(Array.isArray(target.properties.gallery)?target.properties.gallery:[]),source.properties.asset].filter((value,index,array)=>value&&array.indexOf(value)===index);await api(route(`records/${target.id}`),{method:'PUT',body:{...target,properties:{...target.properties,asset:target.properties.asset||source.properties.asset,gallery},version:target.version}});notify(`Image added to ${target.name}.`);},'Add image');},
  'assign-rp-image':d=>formModal('Assign RP image',`<p class="fine">Choose the NPC, location, or item this captured Discord image belongs to.</p><label>Campaign entry</label><select name="entry" required>${records().filter(row=>['npc','location','item'].includes(row.kind)).sort((a,b)=>a.name.localeCompare(b.name)).map(row=>`<option value="${esc(row.id)}">${esc(row.kind)} · ${esc(row.name)}</option>`).join('')}</select>`,async data=>{await api(route(`images/${d.id}`),{method:'PUT',body:{entry:data.get('entry')}});notify('RP image assigned.');await refresh();},'Assign image'),
  'deliver':d=>formModal('Share a finished piece.',`<label>Delivery</label><select name="mode"><option value="discord">Campaign Discord channel</option><option value="email">Email</option></select><label>Email recipients (comma-separated, if using email)</label><textarea name="recipients" rows="3"></textarea><label class="check-label"><input name="confirm" type="checkbox" required> I have checked the content and recipients and want to send it now.</label><p class="fine">Only party-visible content can be sent. Email requires SMTP configured on the host; Discord requires the bot to be running. No message is sent until you submit.</p>`,async data=>{await api(route('deliver'),{method:'POST',body:{entry:d.id,mode:data.get('mode'),recipients:String(data.get('recipients')).split(',').map(v=>v.trim()).filter(Boolean),confirm:true}});notify('Delivery queued. Check its result in the Actions hub.');},'Send now'),
  'integration-help':()=>modal('Bring the archive to your tools.',`<h3>MCP / developer API</h3><p>Issue a scoped personal key in Settings. Configure your MCP client to run <code>node /absolute/path/to/src/mcp.js</code>, with <code>CHRONICLE_URL</code> and <code>CHRONICLE_ACCESS_TOKEN</code> in its environment. The dashboard must be running. Read and write access follow your key and member role.</p><h3>Foundry VTT</h3><p>The source package includes <code>integrations/foundry/</code>. Install its module folder, configure the Chronicle URL and a scoped key, then use the import action to bring party-visible entries into Foundry journals.</p><h3>Obsidian</h3><p>Use Export Obsidian vault for a direct Markdown snapshot with [[wiki links]]. An optional plugin source is included for authenticated import and journal push.</p><p class="fine">Integrations still need a live test in your own applications. External services are never connected automatically.</p>`),
  'graph-open':()=>state.graph?.focus?openRecord(state.graph.focus):notify('Select a map node first.'),
};
function editCast(row={}) {formModal(row.id?'Edit cast member':'Add cast member',`<label>Player name</label><input name="player" required value="${esc(row.player||'')}"><label>Character name</label><input name="character" value="${esc(row.character||'')}"><label>Discord user ID / member subject</label><input name="subject" value="${esc(row.subject||'')}"><label>Role</label><select name="role"><option ${row.role==='player'?'selected':''}>player</option><option ${row.role==='gm'?'selected':''}>gm</option></select><label>Aliases, comma-separated</label><input name="aliases" value="${esc((row.aliases||[]).join(', '))}"><label>Linked player-character entry</label><select name="entity"><option value="">None</option>${records('pc').map(r=>`<option value="${r.id}" ${row.entity===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select>`,async data=>{const body=Object.fromEntries(data);body.aliases=body.aliases.split(',').map(v=>v.trim()).filter(Boolean);body.entity=body.entity||null;await api(route('cast'+(row.id?'/'+row.id:'')),{method:row.id?'PUT':'POST',body});notify('Cast member saved.');});}

Object.assign(actions,{
  'ov-listen':d=>{const session=state.data.sessions.find(s=>s.id===d.id),btn=document.querySelector(`[data-action="ov-listen"][data-id="${d.id}"]`);if(!session||!btn)return;
    const reset=()=>{ovSpeaking=null;btn.innerHTML=`${ovIcon('play')} Listen to recap`;};
    if(ovSpeaking===session.id){speechSynthesis.cancel();reset();return;}
    speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(`${session.title}. ${ovPlain(session.recap)}`);u.onend=u.onerror=()=>{if(ovSpeaking===session.id)reset();};ovSpeaking=session.id;btn.innerHTML=`${ovIcon('stop')} Stop`;speechSynthesis.speak(u);},
  'ov-kind':async d=>{await navigate('wiki');state.filter=d.kind;await render();},
  'ov-note-save':async()=>{const body=$('#ov-note').value,note=ovMyNote();
    if(note)await api(route('records/'+note.id),{method:'PUT',body:{...note,body,version:note.version}});
    else await api(route('records'),{method:'POST',body:{kind:'journal',name:'My note',body,visibility:'private'}});
    await refresh();notify('Note saved. Only you can see it.');},
});
document.addEventListener('click',async event=>{
  const action=event.target.closest('[data-action]');if(action){event.preventDefault();try{await actions[action.dataset.action]?.(action.dataset);}catch(error){notify(error.message,true);}return;}
  const view=event.target.closest('[data-view]');if(view){try{await navigate(view.dataset.view);}catch(error){notify(error.message,true);}}
});
document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.matches('.entry-card'))event.target.click();});
document.addEventListener('input',event=>{
  if(event.target.id==='list-search'){const cursor=event.target.selectionStart;state.query=event.target.value;clearTimeout(state.searchTimer);state.searchTimer=setTimeout(async()=>{await render();const input=$('#list-search');input?.focus();input?.setSelectionRange(cursor,cursor);},220);}
  if(event.target.id==='graph-search'){state.graph.focus=null;drawGraph();}
});
document.addEventListener('change',async event=>{try{
  if(['session-filter','folder-filter'].includes(event.target.id)){state.filter=event.target.value;await render();}
  if(event.target.id==='graph-filter'){state.graph.focus=null;drawGraph();}
  if(event.target.dataset.objective){const row=records().find(r=>r.id===event.target.dataset.quest),props=structuredClone(row.properties);props.objectives[Number(event.target.dataset.objective)].status=event.target.value;const statuses=props.objectives.map(o=>o.status);props.status=statuses.every(s=>s==='done')?'done':statuses.includes('failed')?'failed':statuses.includes('blocked')?'blocked':statuses.some(s=>['in_progress','done'].includes(s))?'in_progress':'planned';await api(route('records/'+row.id),{method:'PUT',body:{...row,properties:props}});await refresh();notify('Quest updated.');}
}catch(error){notify(error.message,true);}});
$('#login-form').onsubmit=event=>{event.preventDefault();state.token=$('#access-key').value.trim();sessionStorage.setItem('chronicle-key',state.token);boot();};
$('#logout').onclick=()=>{state.token='';state.data=null;sessionStorage.removeItem('chronicle-key');boot();};
$('#campaign-picker').onchange=async event=>{state.campaign=event.target.value;state.view='overview';await refresh();};
$('#create-campaign').onclick=actions['create-campaign'];$('#home-link').onclick=event=>{event.preventDefault();navigate('overview');};
$('#refresh').onclick=()=>refresh().catch(error=>notify(error.message,true));$('#mobile-menu').onclick=()=>$('.sidebar').classList.toggle('open');
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',event=>{if(event.target===$('#modal'))$('#modal').close();});
$('#global-search').onsubmit=async event=>{event.preventDefault();state.query=$('#search-input').value;state.view='search';try{await render();}catch(error){notify(error.message,true);}};
const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.get('token')){state.token=fragment.get('token');sessionStorage.setItem('chronicle-key',state.token);history.replaceState(null,'',location.pathname);}
const {setupAdvanced}=await import('/advanced.js');
setupAdvanced({state,api,route,records,admin,button,modal,formModal,notify,refresh,render,esc,openRecord,views,actions,drawGraph});
await boot();
setInterval(async()=>{if(!state.campaign||!state.token||!state.data)return;try{const updated=await api(route('state'));const changed=JSON.stringify(updated.jobs)!==JSON.stringify(state.data.jobs)||updated.reviews.length!==state.data.reviews.length;state.data=updated;$('#review-badge').textContent=updated.reviews.filter(r=>r.state==='pending').length||'';if(changed&&!$('#modal').open&&!document.activeElement?.matches('input,textarea')&&['overview','settings','reviews'].includes(state.view))await render();}catch{}},7000);
